schema_ddl:
CREATE TABLE ITP (
    ITEMN INT,
    PONUM INT
);
CREATE TABLE ITM (
    ITEMN INT,
    TYPE INT,
    PRIMARY KEY (ITEMN)
);
CREATE TABLE PUR (
    PONUM INT,
    ODATE INT,
    VENDN INT
);

